// Generated by unbrowse-sdk/codegen/generate.py from unbrowse-node/agent-api.json. Never edit it by hand: change the
// node's registries, rewrite agent-api.json, then run `python3 unbrowse-sdk/codegen/generate.py` (`npm run gen`). The
// node's records as they cross the wire, in its own snake case, exactly as its schemas say; the agent primitives'
// requests; and the owner client's base, with one method per owner command. The hand-written client (client.ts,
// owner.ts) sits on top of it.

// ---- the node's contract ----

/** The port a node listens on until its owner names another. */
export const DEFAULT_PORT = 7788;
/** How long a client waits for one call: `do` may walk a page, and a call may heal by walking it again. */
export const CALL_WAIT_MS = 330000;

/** What a failed call means: its code (from the answer's status, or the code its body names), the status, the
 * class the SDK raises for it (none: a plain `UnbrowseError`) and what it says. Status 0 is the client's own. */
export const ERRORS = [
  { code: "bad_request", status: 400, class: "BadRequestError", means: "a call the node couldn't run with these inputs; an owner command that failed" },
  { code: "unauthorized", status: 401, class: "AuthenticationError", means: "no token, or a key that is unknown, revoked or expired" },
  { code: "payment_required", status: 402, class: "PaymentRequiredError", means: "a paid route this key isn't authorised for, past its cap, or costing more to fetch than the owner's per-fetch maximum (the message names both)" },
  { code: "forbidden", status: 403, class: "PermissionDeniedError", means: "the owner declined (or didn't answer in time), turned learning off, or excluded the site" },
  { code: "not_found", status: 404, class: "NotFoundError", means: "no such route, owner command or walk picture; or nothing does the goal yet and no url was given" },
  { code: "conflict", status: 409, class: "ConflictError", means: "routes on more than one site do the goal: give url to say which" },
  { code: "unprocessable", status: 422, class: "UnprocessableEntityError", means: "the browser or the learner couldn't do it; the message says why" },
  { code: "browser_missing", status: 422, class: "BrowserMissingError", means: "the goal needs the node's browser and the node has none, and the error says what's missing and how to get it; or the call said browser=\"never\", and the error says it was declined (declined: true, outcome browser_declined), with nothing to install" },
  { code: "bad_gateway", status: 502, class: "", means: "the site, or the network a call went through, failed" },
  { code: "unavailable", status: 503, class: "NodeUnavailableError", means: "the node is paused by its owner, waiting for Keychain access, or unable to read the sessions it holds to keep them out of an answer" },
  { code: "unreachable", status: 0, class: "NodeConnectionError", means: "the node isn't running, or nothing answers at its address" },
  { code: "timeout", status: 0, class: "NodeTimeoutError", means: "the node didn't answer in time" },
] as const;

