// ---- the agent API ----

/** What each agent primitive takes and answers, by its tool's name. */
export interface AgentPrimitives {
  unbrowse_search: {
    args: { query?: string };
    result: { routes: Route[]; checked?: boolean };
  };
  unbrowse_do: {
    args: {
      /** Plain words; the same ones find the same route. Needed unless ask. */
      goal?: string;
      /** ms; default 45000, max 300000. Then, still working (learning, waiting for the site's browser): outcome still_working with ask and next; work goes on. */
      wait_ms?: number;
      /** From a still_working reply: collects the answer, waiting up to wait_ms again. Kept 5 min after the work ends. Alone: it holds the rest. */
      ask?: string;
      url?: string;
      /** By route.inputs names; win over the url's. */
      inputs?: Record<string, string>;
      session?: string;
      /** Extra paths from result.fields.more (items[].rating; a list or object brings all of it), or ["*"]. Default: the goal's fields and each record's name. Ask only for what you need. */
      fields?: string[];
      /** Instead of url, max 100 (objects or url strings), side by side; a page's goal and inputs win. Reply how: pages, each page's how, ms, data or error, in order. A site's first page goes first; its route answers the rest. A how: browse page isn't opened: ask it alone. Past wait_ms (40 s unsaid), pages still learning are in pending (how: working); the batch's ask (in next) collects all, a page's own ask that page. */
      pages?: { url: string; goal?: string; inputs?: Record<string, string> }[];
      /** auto (default): when needed, fetched if missing and the owner allows; if_present: only one present; never: routes, network routes, plain requests only. Missing: outcome browser_missing, saying how to get it; ruled out: outcome browser_declined, declined: true, next: the call with browser auto. */
      browser?: "auto" | "if_present" | "never";
      /** USDC this task pays at most to fetch one network route (e.g. 0.01); a fee over it is passed over (network_skipped). Only lowers the owner's max. */
      budget_usdc?: number;
    };
    result: DoResult;
  };
  unbrowse_walk: {
    args: {
      url: string;
      goal?: string;
      pick?: number;
      /** Your name for the picked call; default goal. */
      what?: string;
      session?: string;
    };
    result: {
      walk: string;
      url: string;
      site: string;
      candidates: {
        index: number;
        method: string;
        host: string;
        path: string;
        status: number;
        bytes: number;
        keys: string[];
        page: boolean;
        /** What the answer holds, read from its own shape: records (a list of objects with fields: what a reader came for), words (a list of plain strings: a search's suggestions), object, text, empty, or page. */
        shape: string;
        /** One of the call's request keys is a name in the page's own scripts, and its value is one the walk cannot source: the page's own code made it, so a route on this call computes it in the sandbox and needs no browser for it. */
        writes: boolean;
      }[];
      /** The route kept from pick, as unbrowse_do's route. */
      route?: Record<string, unknown>;
    };
  };
  unbrowse_browse: {
    args: {
      do: string[];
      site?: string;
      goal?: string;
      /** One tab each; MCP uses your client's. Name one to keep pages apart (over HTTP, from other agents on your key). The SDKs send one per client. */
      session?: string;
      /** ask_owner: ms before still_working; 45000 unsaid. */
      wait_ms?: number;
    };
    result: BrowseReply;
  };
  unbrowse_challenge: {
    args: {
      action: "look" | "click" | "drag" | "hold" | "type" | "press" | "wait" | "done" | "solve";
      /** Opened first; omit for the open page. */
      url?: string;
      site?: string;
      session?: string;
      x?: number;
      y?: number;
      to_x?: number;
      to_y?: number;
      text?: string;
      key?: "Enter" | "Tab" | "Escape" | "Backspace";
      ms?: number;
      /** A hand step (click/drag/type/press) with no picture or read after it, to beat a short timer when you hold the grid already; look afterwards. */
      quick?: boolean;
      /** Hand steps ({action,x,y,...}) landed in one go, no picture between: a grid's clicks and Confirm inside a short timer. Overrides action. */
      steps?: Record<string, unknown>[];
    };
    result: ChallengeReply;
  };
  unbrowse_observe: {
    args: { site?: string; session?: string; goal?: string };
    result: {
      site: string;
      elements: {
        ref: string;
        role: string;
        name: string;
        actions: string[];
        disabled?: boolean;
        checked?: boolean;
        value?: string;
      }[];
    };
  };
  unbrowse_logins: {
    args: Record<string, never>;
    result: { logins: Login[]; cards: Card[]; sign_up: string };
  };
  unbrowse_open: {
    args: { link: string };
    result: LinkPreview;
  };
  unbrowse_call: {
    args: {
      route_id: string;
      inputs?: Record<string, string>;
      /** Use never for replay only. Default auto allows browser fallback. */
      browser?: "auto" | "never";
      fields?: string[];
    };
    result: CallResult;
  };
  unbrowse_inspect: {
    args: {
      /** From unbrowse_do, unbrowse_call or unbrowse_walk. */
      route_id: string;
    };
    result: {
      route: Record<string, unknown>;
      browser: boolean;
      scripts: { count: number; bytes: number };
      steps: Record<string, unknown>[];
      describe: string;
    };
  };
  unbrowse_judge: {
    args: {
      /** route.id or route_failed.route_id from a reply. */
      route_id: string;
      verdict: "right" | "wrong";
      url?: string;
      why?: string;
      what?: string;
      fields?: string[];
      /** Rewire values unbrowse_inspect shows. is: fixed (the walk's value), drop (an unneeded header), session (a header from page storage), input:<name> (the caller's input), from:<step>:<json pointer> (read each call from that step's answer), keep. Kept only if the walk and the site both answer, with word too, and word gets its own answer; else unchanged, the error says why. Alone, with verdict right; never on a write. */
      links?: {
        /** From 1, as unbrowse_inspect numbers it. */
        step: number;
        /** unbrowse_inspect's at (header:x-request-id, json:/variables/id). */
        at: string;
        is: string;
      }[];
      /** With links: another value the site surely answers there; default the one already asked. */
      word?: string;
      /** true: calling changes the site whatever its method (even a GET): a write from then on, held to write rules, never called to read. false undoes it. */
      writes?: boolean;
      bounty?: number;
      entry?: string;
    };
    result: JudgeResult | BountyAnswer;
  };
  unbrowse_whoami: {
    args: Record<string, never>;
    result: Whoami;
  };
  unbrowse_setup: {
    args: {
      do?: "accept_terms" | "sign_in" | "connect_apps" | "tools" | "web" | "connect_site";
      host?: string;
    };
    result: Setup;
  };
  unbrowse_report: {
    args: {
      kind: "wrong_data" | "false_success" | "failed" | "slow" | "confusing" | "other";
      /** One line. */
      summary: string;
      expected: string;
      /** Trimmed. */
      got: string;
      route_id?: string;
      /** Your unbrowse_do goal, if part of it. */
      goal?: string;
      /** Scheme, host and path kept. */
      url?: string;
      /** Whose answer was wrong. */
      tool?: "unbrowse_search" | "unbrowse_do" | "unbrowse_browse" | "unbrowse_logins" | "unbrowse_call" | "unbrowse_whoami";
      error?: string;
    };
    result: ReportResult;
  };
}
export type PrimitiveArgs<P extends keyof AgentPrimitives> = AgentPrimitives[P]["args"];
export type PrimitiveResult<P extends keyof AgentPrimitives> = AgentPrimitives[P]["result"];

/** A primitive's route: its method and path, the arguments it takes, and the names `unb` and the SDKs give it. */
export type PrimitiveSpec = {
  readonly tool: string;
  readonly method: "GET" | "POST";
  readonly path: string;
  /** The arguments whose name over HTTP differs from the tool's. */
  readonly renamed: readonly { readonly http: string; readonly tool: string }[];
  readonly args: readonly string[];
  readonly required: readonly string[];
  readonly sdk: readonly string[];
  readonly cli: string;
};

export const PRIMITIVES = {
  unbrowse_search: { tool: "unbrowse_search", method: "GET", path: "/v1/routes", renamed: [{ http: "q", tool: "query" }], args: ["query"], required: [], sdk: ["search"], cli: "search" },
  unbrowse_do: { tool: "unbrowse_do", method: "POST", path: "/v1/do", renamed: [], args: ["ask", "browser", "budget_usdc", "fields", "goal", "inputs", "pages", "session", "url", "wait_ms"], required: [], sdk: ["do"], cli: "do" },
  unbrowse_walk: { tool: "unbrowse_walk", method: "POST", path: "/v1/walk", renamed: [], args: ["goal", "pick", "session", "url", "what"], required: ["url"], sdk: ["walk"], cli: "walk" },
  unbrowse_browse: { tool: "unbrowse_browse", method: "POST", path: "/v1/browse", renamed: [], args: ["do", "goal", "session", "site", "wait_ms"], required: ["do"], sdk: ["browser", "browse"], cli: "browse" },
  unbrowse_challenge: { tool: "unbrowse_challenge", method: "POST", path: "/v1/challenge", renamed: [], args: ["action", "key", "ms", "quick", "session", "site", "steps", "text", "to_x", "to_y", "url", "x", "y"], required: ["action"], sdk: ["challenge"], cli: "challenge" },
  unbrowse_observe: { tool: "unbrowse_observe", method: "POST", path: "/v1/observe", renamed: [], args: ["goal", "session", "site"], required: [], sdk: ["observe"], cli: "observe" },
  unbrowse_logins: { tool: "unbrowse_logins", method: "GET", path: "/v1/logins", renamed: [], args: [], required: [], sdk: ["logins", "cards"], cli: "logins" },
  unbrowse_open: { tool: "unbrowse_open", method: "GET", path: "/v1/open", renamed: [{ http: "q", tool: "link" }], args: ["link"], required: ["link"], sdk: ["open"], cli: "open" },
  unbrowse_call: { tool: "unbrowse_call", method: "POST", path: "/v1/routes/{id}/call", renamed: [{ http: "id", tool: "route_id" }], args: ["browser", "fields", "inputs", "route_id"], required: ["route_id"], sdk: ["call"], cli: "call" },
  unbrowse_inspect: { tool: "unbrowse_inspect", method: "GET", path: "/v1/routes/{id}/inspect", renamed: [{ http: "id", tool: "route_id" }], args: ["route_id"], required: ["route_id"], sdk: ["inspect"], cli: "inspect" },
  unbrowse_judge: { tool: "unbrowse_judge", method: "POST", path: "/v1/routes/{id}/judge", renamed: [{ http: "id", tool: "route_id" }], args: ["bounty", "entry", "fields", "links", "route_id", "url", "verdict", "what", "why", "word", "writes"], required: ["route_id", "verdict"], sdk: ["judge"], cli: "judge" },
  unbrowse_whoami: { tool: "unbrowse_whoami", method: "GET", path: "/v1/whoami", renamed: [], args: [], required: [], sdk: ["whoami"], cli: "whoami" },
  unbrowse_setup: { tool: "unbrowse_setup", method: "POST", path: "/v1/setup", renamed: [], args: ["do", "host"], required: [], sdk: ["setup"], cli: "setup" },
  unbrowse_report: { tool: "unbrowse_report", method: "POST", path: "/v1/report", renamed: [], args: ["error", "expected", "goal", "got", "kind", "route_id", "summary", "tool", "url"], required: ["kind", "summary", "expected", "got"], sdk: ["report"], cli: "report" },
} as const satisfies Record<keyof AgentPrimitives, PrimitiveSpec>;

/**
 * A primitive's request as its `/v1` route takes it: each argument by its HTTP name, a path's own in the path and
 * the rest in a GET's query or a POST's JSON body. An argument left out is left out of the request.
 */
export function primitiveRequest<P extends keyof AgentPrimitives>(
  tool: P,
  args: PrimitiveArgs<P>,
): { method: "GET" | "POST"; path: string; body?: Record<string, unknown> } {
  const spec: PrimitiveSpec = PRIMITIVES[tool];
  const given = args as Record<string, unknown>;
  const http = (name: string) => spec.renamed.find((r) => r.tool === name)?.http ?? name;
  const rest: [string, unknown][] = [];
  let path = spec.path;
  for (const name of spec.args) {
    const slot = `{${http(name)}}`;
    if (path.includes(slot)) path = path.replace(slot, encodeURIComponent(String(given[name])));
    else if (given[name] !== undefined) rest.push([http(name), given[name]]);
  }
  if (spec.method === "POST") return { method: "POST", path, body: Object.fromEntries(rest) };
  const query = rest.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`).join("&");
  return { method: "GET", path: query ? `${path}?${query}` : path };
}

